<?php
/**
 * Enterprise DigiVerify
 * verification_result.php
 *
 * Displays verification result.
 *
 * Supported:
 * APPROVED
 * REJECTED
 *
 * IMPORTANT:
 * This page displays the result generated by the verification engine.
 * It does NOT independently authenticate Aadhaar with UIDAI.
 */

declare(strict_types=1);

/* =========================================================
   SECURITY / HELPERS
========================================================= */

function e(mixed $value): string
{
    return htmlspecialchars(
        (string)$value,
        ENT_QUOTES,
        'UTF-8'
    );
}

function getParam(
    string $key,
    string $default = ''
): string {
    return isset($_GET[$key])
        ? trim((string)$_GET[$key])
        : $default;
}

function getListParam(
    string $key
): array {

    $value = getParam($key);

    if ($value === '') {
        return [];
    }

    $items = explode('|', $value);

    $items = array_map(
        'trim',
        $items
    );

    $items = array_filter(
        $items,
        static fn($item) => $item !== ''
    );

    return array_values(
        array_unique($items)
    );
}

/* =========================================================
   RESULT PARAMETERS
========================================================= */

$status = strtoupper(
    getParam(
        'status',
        'REJECTED'
    )
);

/*
 * Only two possible results.
 */
if ($status !== 'APPROVED') {
    $status = 'REJECTED';
}

/* =========================================================
   SCORE
========================================================= */

$score = (int)getParam(
    'score',
    '0'
);

$score = max(
    0,
    min(
        100,
        $score
    )
);

/* =========================================================
   DOCUMENT DETAILS
========================================================= */

$name = getParam(
    'name',
    'NOT DETECTED'
);

if ($name === '') {
    $name = 'NOT DETECTED';
}

$aadhaar = getParam(
    'aadhaar',
    'XXXX XXXX XXXX'
);

if ($aadhaar === '') {
    $aadhaar = 'XXXX XXXX XXXX';
}

/* =========================================================
   REASONS / WARNINGS
========================================================= */

$reasons = getListParam('reason');

$warnings = getListParam('warning');

/*
 * Default messages
 */
if (empty($reasons)) {

    if ($status === 'APPROVED') {

        $reasons[] =
            'Document screening criteria were successfully detected.';

    } else {

        $reasons[] =
            'Required document verification indicators were not sufficiently detected.';
    }
}

if (empty($warnings)) {

    $warnings[] =
        'This result is generated by the DigiVerify project-level verification engine.';
}

/* =========================================================
   STATUS UI
========================================================= */

if ($status === 'APPROVED') {

    $statusClass = 'approved';

    $statusIcon = '✓';

    $statusTitle =
        'VERIFICATION APPROVED';

    $statusSubtitle =
        'AI SCREENING PASSED';

    $statusDescription =
        'The uploaded document satisfied the configured DigiVerify screening criteria.';

} else {

    $statusClass = 'rejected';

    $statusIcon = '×';

    $statusTitle =
        'VERIFICATION REJECTED';

    $statusSubtitle =
        'AI SCREENING FAILED';

    $statusDescription =
        'The uploaded document did not satisfy the configured DigiVerify screening criteria.';
}

/* =========================================================
   DATE / TIME
========================================================= */

$dateTime = date(
    'd M Y, h:i A'
);

?>
